# region: sift
def sift(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: emit
def emit(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: render
def render(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return render(intake(digest(emit(sift(raw)))))

